// --- Sparse-CBOR write. ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around TrailViewerLaunchBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// TrailViewerLaunchEntityI.
func (c *TrailViewerLaunchColumns) Marshal(w io.Writer) (err error) {
	ent := trailViewerLaunchPool.Get().(*cbdml.InEntityFacts)
	defer trailViewerLaunchPool.Put(ent)
	ent.SetActiveSections(TrailViewerLaunchActiveSections)
	ent.Builder().SetActiveFields(TrailViewerLaunchActiveFields())
	err = TrailViewerLaunchBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("launchcfg: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("launchcfg: marshal write: %w", err)
	}
	return
}

