// Unmarshal appends one row to c per entity in rec, projecting
// the boxer.facts columns through factsschema/ra. Thin wrapper
// around TrailViewerLaunchFillFromArrow — the per-row decode lives there.
func (c *TrailViewerLaunchColumns) Unmarshal(rec arrow.Record) (err error) {
	r := newTrailViewerLaunchReader()
	defer r.release()
	err = r.loadFromRecord(rec)
	if err != nil {
		return
	}
	n := r.EntityId.Len()
	err = TrailViewerLaunchFillFromArrow(
		c,
		n,
		r.EntityId.ValueId,
		r.EntityId.ValueNaturalKey,
		r.EntityTimestamp.ValueTs,
		r.StringArray.Attributes, r.StringArray.Memberships,
		r.I64Array.Attributes, r.I64Array.Memberships,
	)
	return
}

// --- buscodec.CodecI bridge. ---

// TrailViewerLaunchCodec is the buscodec.CodecI bridge for TrailViewerLaunch. Encodes one row
// through dml_cbor; decodes via cborarrow.Convert + ra-Unmarshal +
// Row(0). Auto-registered in init() so callers using buscodec.Encode
// / Decode route through here instead of the CBOR fallback.
type TrailViewerLaunchCodec struct{}

var _ buscodec.CodecI = (*TrailViewerLaunchCodec)(nil)

// trailViewerLaunchBusCodec is the package-local singleton wired into buscodec.
var trailViewerLaunchBusCodec = &TrailViewerLaunchCodec{}

func (inst *TrailViewerLaunchCodec) Name() (n string) {
	n = "trailViewerLaunch-sparse-cbor"
	return
}

func (inst *TrailViewerLaunchCodec) ContentType() (ct string) {
	ct = "application/x-runtime-facts+rb;kind=trailViewerLaunch"
	return
}

func (inst *TrailViewerLaunchCodec) Encode(v any) (b []byte, err error) {
	var row TrailViewerLaunch
	switch x := v.(type) {
	case TrailViewerLaunch:
		row = x
	case *TrailViewerLaunch:
		if x == nil {
			err = eh.Errorf("launchcfg: Encode nil *TrailViewerLaunch")
			return
		}
		row = *x
	default:
		err = eh.Errorf("launchcfg: Encode requires TrailViewerLaunch or *TrailViewerLaunch, got %T", v)
		return
	}
	cols := &TrailViewerLaunchColumns{}
	cols.Append(row)
	var buf bytes.Buffer
	err = cols.Marshal(&buf)
	if err != nil {
		err = eh.Errorf("launchcfg: Encode marshal: %w", err)
		return
	}
	b = buf.Bytes()
	return
}

func (inst *TrailViewerLaunchCodec) Decode(b []byte, v any) (err error) {
	target, ok := v.(*TrailViewerLaunch)
	if !ok {
		err = eh.Errorf("launchcfg: Decode requires *TrailViewerLaunch, got %T", v)
		return
	}
	var arrowBuf bytes.Buffer
	err = cborarrow.Convert(bytes.NewReader(b), &arrowBuf)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode cborarrow: %w", err)
		return
	}
	rd, err := ipc.NewReader(&arrowBuf)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode ipc reader: %w", err)
		return
	}
	defer rd.Release()
	if !rd.Next() {
		err = eh.Errorf("launchcfg: Decode expected one Arrow record, got none")
		return
	}
	rec := rd.RecordBatch()
	defer rec.Release()
	cols := &TrailViewerLaunchColumns{}
	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("launchcfg: Decode expected 1 row")
		return
	}
	*target = cols.Row(0)
	return
}
